.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 42px; padding: 0 14px; border: 1px solid transparent; border-radius: 6px; font: 690 13px/1.25 var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); white-space: nowrap; background: var(--accent-fill, #edb773); color: var(--on-accent, #251910); cursor: pointer; }
.ds-button-primary:hover:not(:disabled) { background: var(--accent-strong, #f6c88e); }
.ds-button-primary:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
.ds-button-primary:disabled { cursor: default; opacity: .49; }
@media (prefers-reduced-motion: no-preference) { .ds-button-primary { transition: color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), background-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), border-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)); } .ds-button-primary:active:not(:disabled) { translate: 0 1px; } }

.ds-button-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 42px; padding: 0 14px; border: 1px solid var(--control-line, #786a58); border-radius: 6px; font: 690 13px/1.25 var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); white-space: nowrap; background: var(--surface, #25221e); color: var(--ink, #f4ece0); cursor: pointer; }
.ds-button-secondary:hover:not(:disabled) { background: var(--raised, #302c26); }
.ds-button-secondary:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
.ds-button-secondary:disabled { cursor: default; opacity: .49; }
@media (prefers-reduced-motion: no-preference) { .ds-button-secondary { transition: color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), background-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), border-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)); } .ds-button-secondary:active:not(:disabled) { translate: 0 1px; } }

.ds-button-destructive { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 42px; padding: 0 14px; border: 1px solid transparent; border-radius: 6px; font: 690 13px/1.25 var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); white-space: nowrap; background: var(--danger-fill, #a23d34); color: var(--on-danger, #fff9f5); cursor: pointer; }
.ds-button-destructive:hover:not(:disabled) { filter: brightness(1.12); }
.ds-button-destructive:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
.ds-button-destructive:disabled { cursor: default; opacity: .49; }
@media (prefers-reduced-motion: no-preference) { .ds-button-destructive { transition: color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), background-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), border-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)); } .ds-button-destructive:active:not(:disabled) { translate: 0 1px; } }

.ds-button-link { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 42px; padding: 0 4px; border: 1px solid transparent; border-radius: 6px; font: 690 13px/1.25 var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); white-space: nowrap; background: transparent; color: var(--accent, #edb773); cursor: pointer; }
.ds-button-link:hover:not(:disabled) { text-decoration: underline; text-underline-offset: 4px; }
.ds-button-link:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
.ds-button-link:disabled { cursor: default; opacity: .49; }
@media (prefers-reduced-motion: no-preference) { .ds-button-link { transition: color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), background-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), border-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)); } .ds-button-link:active:not(:disabled) { translate: 0 1px; } }

.ds-icon-toggle { width: 36px; height: 36px; display: inline-grid; place-items: center; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--ink, #f4ece0); cursor: pointer; }
.ds-icon-toggle:hover:not(:disabled) { background: var(--raised, #302c26); }
.ds-icon-toggle[aria-pressed=true] { background: var(--accent-tint, #3f3022); color: var(--accent, #edb773); }
.ds-icon-toggle:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
@media (prefers-reduced-motion: no-preference) { .ds-icon-toggle { transition: color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), background-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), border-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)); } }

.ds-search { display: flex; align-items: center; gap: 9px; min-height: 42px; width: min(100%, 540px); box-sizing: border-box; padding: 0 10px; border: 1px solid var(--control-line, #786a58); border-radius: 6px; background: var(--field, #1c1a17); color: var(--muted, #bcb0a0); }
.ds-search > svg { flex-shrink: 0; }
.ds-search input { width: 100%; min-width: 0; min-height: 39px; padding: 0; border: 0; outline: none; font: 14px var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); background: transparent; color: var(--ink, #f4ece0); }
.ds-search input::placeholder { opacity: 1; color: var(--muted, #bcb0a0); }
.ds-search:focus-within { outline: 2px solid var(--accent, #edb773); outline-offset: 2px; }
.ds-search kbd { flex: 0 0 auto; white-space: nowrap; border: 1px solid var(--border, #4a4136); border-radius: 4px; padding: 4px 5px; background: var(--surface, #25221e); color: var(--muted, #bcb0a0); font: 11px var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); }
@media (max-width: 550px) { .ds-search { min-height: 44px; } .ds-search kbd { display: none; } }

.ds-nav { display: grid; gap: 3px; padding: 8px; background: var(--sidebar, #201e1b); }
.ds-nav-item { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 42px; padding: 0 11px; border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--muted, #bcb0a0); font: 580 14px var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); text-align: left; cursor: pointer; }
.ds-nav-item:hover { background: var(--raised, #302c26); color: var(--ink, #f4ece0); }
.ds-nav-item[aria-current=page] { background: var(--accent-tint, #3f3022); border-color: color-mix(in srgb, var(--accent, #edb773) 25%, var(--line, #3b352d)); color: var(--accent, #edb773); font-weight: 680; }
.ds-nav-item:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
@media (prefers-reduced-motion: no-preference) { .ds-nav-item { transition: color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), background-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), border-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)); } }

.ds-doc-card { position: relative; min-width: 0; border: 1px solid var(--line, #3b352d); border-radius: 7px; background: var(--canvas, #181715); color: var(--ink, #f4ece0); font-family: var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); --ds-cover: #dce7d8; --ds-cover-ink: #43634a; }
.ds-doc-card:hover, .ds-doc-card:focus-within { border-color: var(--control-line, #786a58); background: var(--sidebar, #201e1b); }
.ds-doc-open { display: block; width: 100%; padding: 0; border: 0; border-radius: inherit; background: transparent; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.ds-doc-cover { height: clamp(132px, 16vw, 205px); display: grid; place-items: center; overflow: hidden; border-radius: 6px 6px 0 0; border-bottom: 1px solid var(--line, #3b352d); background: var(--sidebar, #201e1b); }
.ds-doc-object { box-sizing: border-box; display: flex; flex-direction: column; justify-content: space-between; gap: 5px; width: 43%; max-width: 136px; min-width: 83px; aspect-ratio: .78; max-height: 84%; overflow: hidden; padding: 12px 9px 11px 16px; border: 1px solid color-mix(in srgb, var(--ds-cover-ink) 23%, var(--ds-cover)); border-radius: 3px 6px 6px 3px; background: var(--ds-cover); color: color-mix(in srgb, var(--ds-cover-ink) 84%, #24180f); box-shadow: 2px 5px 11px #0e0b0850, inset 5px 0 color-mix(in srgb, var(--ds-cover-ink) 13%, var(--ds-cover)); }
.ds-doc-object > span { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; font: 670 clamp(11px, 1.2vw, 16px)/1.14 var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); letter-spacing: -.035em; }
.ds-doc-details { box-sizing: border-box; min-height: 58px; display: flex; flex-direction: column; justify-content: center; gap: 3px; padding: 7px 55px 7px 11px; }
.ds-doc-details strong { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-size: 13px; font-weight: 690; }
.ds-doc-meta { display: flex; flex-wrap: wrap; gap: 2px 6px; color: var(--muted, #bcb0a0); font-size: 11px; line-height: 1.25; }
.ds-doc-meta > span:not(:first-child)::before { content: ''; display: inline-block; width: 2px; height: 2px; vertical-align: .25em; margin-right: 6px; border-radius: 50%; background: currentColor; }
.ds-doc-menu { position: absolute; right: 6px; bottom: 11px; display: inline-grid; place-items: center; width: 34px; height: 34px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--muted, #bcb0a0); cursor: pointer; }
.ds-doc-menu:hover { background: var(--raised, #302c26); color: var(--ink, #f4ece0); }
.ds-doc-open:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
.ds-doc-menu:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
@media (prefers-reduced-motion: no-preference) { .ds-doc-card { transition: color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), background-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)), border-color 140ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)); } }
@media (max-width: 550px) { .ds-doc-cover { height: 132px; } .ds-doc-object { min-width: 98px; padding-inline: 13px 7px; } .ds-doc-details { min-height: 72px; padding-inline: 8px 42px; } .ds-doc-details strong { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; white-space: normal; overflow-wrap: anywhere; font-size: 12px; } .ds-doc-menu { right: 3px; bottom: 7px; width: 37px; height: 44px; } }

.ds-dialog { position: relative; box-sizing: border-box; width: min(465px, calc(100% - 28px)); margin: 0 auto; padding: 21px; overflow: auto; border: 1px solid var(--border, #4a4136); border-radius: 10px; background: var(--surface, #25221e); color: var(--ink, #f4ece0); box-shadow: 0 16px 50px var(--shadow, #0007); font-family: var(--sans, 'DM Sans Variable', 'Segoe UI', sans-serif); }
.ds-dialog::backdrop { background: var(--scrim, #0d0c0ac9); }
.ds-dialog header { display: flex; align-items: center; justify-content: space-between; gap: 11px; margin-bottom: 13px; }
.ds-dialog h2 { margin: 0; font-size: 24px; line-height: 1.1; font-weight: 700; letter-spacing: -.035em; }
.ds-dialog p { margin: 10px 0 0; color: var(--muted, #bcb0a0); font-size: 14px; line-height: 1.5; }
.ds-dialog-close { display: inline-grid; place-items: center; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--ink, #f4ece0); cursor: pointer; }
.ds-dialog-close:hover { background: var(--raised, #302c26); }
.ds-dialog-close:focus-visible { outline: 2px solid var(--accent, #edb773); outline-offset: 3px; }
@media (prefers-reduced-motion: no-preference) { .ds-dialog { animation: ds-dialog-in 150ms var(--ease-out, cubic-bezier(.2, .8, .2, 1)); } @keyframes ds-dialog-in { from { opacity: 0; translate: 0 -4px; } } }
